-- conferência
select
  (select count(*) from public.nx_metricas_dia where cliente_id = (select id from public.nx_clientes where slug = 'demo-clinica') and nivel = 'anuncio')  as metricas_anuncio,
  (select count(*) from public.nx_metricas_dia where cliente_id = (select id from public.nx_clientes where slug = 'demo-clinica') and nivel = 'campanha') as metricas_campanha,
  (select count(*) from public.nx_leads where cliente_id = (select id from public.nx_clientes where slug = 'demo-clinica')) as pacientes;
